    template <class Handler>
    Subscription subscribe_horizontal_snap_points_changed(Handler&& handler) { return Subscription(detail::subscribe<Self>(this->handle(), 27, std::forward<Handler>(handler))); }
    /// VerticalSnapPointsChanged: the handler takes the object, and may return `true` for handled.
